body.script:
          (async function() {
            try {
              const res = await fetch('https://aeroubg.com/', { cache: 'no-store' });
              if (!res.ok) throw new Error('HTTP ' + res.status);
              const html = await res.text();
              const parser = new DOMParser();
              const doc = parser.parseFromString(html, 'text/html');

              // 1. Copy over all stylesheets and font links
              doc.querySelectorAll('link[rel="stylesheet"], style').forEach(el => {
                document.head.appendChild(el.cloneNode(true));
              });

              // 2. Remove the loading spinner
              document.getElementById('loader')?.remove();

              // 3. Mount root content
              const root = doc.getElementById('root') || doc.body;
              document.body.innerHTML = root.innerHTML;

              // 4. Inject and execute scripts in order
              for (const s of doc.querySelectorAll('script')) {
                const script = document.createElement('script');
                if (s.src) {
                  script.src = s.src;
                } else {
                  script.textContent = s.textContent;
                }
                if (s.type) script.type = s.type;
                document.body.appendChild(script);
              }
            } catch (err) {
              const el = document.getElementById('loader');
              if (el) {
                el.innerHTML = '
Failed to connect to aero. Check your connection.';
              }
            }
          })();
